import{_ as t,o as s,c as e,a2 as o}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"第 9 课：自然语言驱动 —— 用\\"说话\\"来指挥 AI","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-3/lesson-9.md","filePath":"modules/module-3/lesson-9.md"}'),n={name:"modules/module-3/lesson-9.md"};function i(l,a,d,p,r,h){return s(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-9-课-自然语言驱动-——-用-说话-来指挥-ai" tabindex="-1">第 9 课：自然语言驱动 —— 用&quot;说话&quot;来指挥 AI <a class="header-anchor" href="#第-9-课-自然语言驱动-——-用-说话-来指挥-ai" aria-label="Permalink to &quot;第 9 课：自然语言驱动 —— 用&quot;说话&quot;来指挥 AI&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：掌握编写有效指令的方法，学会用自然语言描述需求<br> ⏱️ <strong>预计时长</strong>：25 分钟<br> 🎯 <strong>本节节奏</strong>：讲解 + 对比示例 + 实操</p></blockquote><hr><h2 id="一、什么是-vibe-coding" tabindex="-1">一、什么是&quot;Vibe Coding&quot;？ <a class="header-anchor" href="#一、什么是-vibe-coding" aria-label="Permalink to &quot;一、什么是&quot;Vibe Coding&quot;？&quot;">​</a></h2><p><strong>Vibe Coding</strong> 是一个新词，意思是：<strong>用自然语言描述你想要什么，让 AI 来完成具体实现。</strong></p><p>你不需要写代码，不需要懂技术细节。你只需要：</p><ol><li>清楚地知道你想要什么</li><li>用简洁的语言描述出来</li><li>让 AI 去实现</li></ol><h3 id="类比" tabindex="-1">类比 <a class="header-anchor" href="#类比" aria-label="Permalink to &quot;类比&quot;">​</a></h3><p>想象你在餐厅点菜：</p><ul><li><strong>传统编程方式</strong>：你需要自己买菜、洗菜、切菜、炒菜、调味——每一步都要亲自动手</li><li><strong>Vibe Coding</strong>：你告诉厨师（Codex）&quot;我要一份宫保鸡丁，少辣&quot;，厨师帮你完成所有步骤</li></ul><p><strong>你不需要会做饭，你只需要会点菜。</strong></p><hr><h2 id="二、如何写好-指令" tabindex="-1">二、如何写好&quot;指令&quot; <a class="header-anchor" href="#二、如何写好-指令" aria-label="Permalink to &quot;二、如何写好&quot;指令&quot;&quot;">​</a></h2><h3 id="_2-1-差的指令-vs-好的指令" tabindex="-1">2.1 差的指令 vs 好的指令 <a class="header-anchor" href="#_2-1-差的指令-vs-好的指令" aria-label="Permalink to &quot;2.1 差的指令 vs 好的指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>差的指令 ❌</th><th>好的指令 ✅</th><th>为什么</th></tr></thead><tbody><tr><td>&quot;帮我做个东西&quot;</td><td>&quot;帮我做一个个人简介网页，包含头像、姓名、简介和联系方式&quot;</td><td>具体说明要做什么</td></tr><tr><td>&quot;整理一下文件&quot;</td><td>&quot;把桌面上的文档按日期归类到不同文件夹&quot;</td><td>说明整理规则</td></tr><tr><td>&quot;写个程序&quot;</td><td>&quot;写一个 Python 脚本，读取 CSV 文件并统计每列的平均值&quot;</td><td>说明输入、处理和输出</td></tr><tr><td>&quot;改一下颜色&quot;</td><td>&quot;把页面的主色调从红色改成蓝色，按钮背景色改成深蓝色&quot;</td><td>具体说明改什么</td></tr></tbody></table><h3 id="_2-2-好指令的四个要素" tabindex="-1">2.2 好指令的四个要素 <a class="header-anchor" href="#_2-2-好指令的四个要素" aria-label="Permalink to &quot;2.2 好指令的四个要素&quot;">​</a></h3><p>一个完整的指令应该包含以下要素：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[动作] + [对象] + [规则/要求] + [期望结果]</span></span></code></pre></div><p>举例：</p><ul><li><strong>动作</strong>：帮我整理 / 帮我创建 / 帮我分析</li><li><strong>对象</strong>：这个文件夹 / 这份数据 / 这个网页</li><li><strong>规则</strong>：按文件类型分类 / 去除空行 / 使用蓝色主题</li><li><strong>期望结果</strong>：生成一个报告 / 输出汇总表格 / 保存到指定位置</li></ul><h3 id="_2-3-指令模板" tabindex="-1">2.3 指令模板 <a class="header-anchor" href="#_2-3-指令模板" aria-label="Permalink to &quot;2.3 指令模板&quot;">​</a></h3><p>你可以直接套用这些模板：</p><p><strong>文件操作类：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我 [动作] [对象]，[规则]</span></span>
<span class="line"><span>例如：帮我把这个文件夹里的图片按拍摄日期分类</span></span></code></pre></div><p><strong>内容生成类：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我 [动作] 一个 [类型]，关于 [主题]，要求 [具体要求]</span></span>
<span class="line"><span>例如：帮我写一份关于健康饮食的周报，要求分三个部分</span></span></code></pre></div><p><strong>数据分析类：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我分析 [数据源]，找出 [关注点]，输出 [格式]</span></span>
<span class="line"><span>例如：帮我分析这份销售数据，找出增长最快的产品，输出为表格</span></span></code></pre></div><hr><h2 id="三、学会-追问-和-修正" tabindex="-1">三、学会&quot;追问&quot;和&quot;修正&quot; <a class="header-anchor" href="#三、学会-追问-和-修正" aria-label="Permalink to &quot;三、学会&quot;追问&quot;和&quot;修正&quot;&quot;">​</a></h2><p>Codex 不是一次就能给出完美结果的。关键在于<strong>学会追问</strong>。</p><h3 id="场景演示" tabindex="-1">场景演示 <a class="header-anchor" href="#场景演示" aria-label="Permalink to &quot;场景演示&quot;">​</a></h3><p>假设你要 Codex 帮你做一个网页：</p><p><strong>第一轮：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我做一个个人简介网页</span></span>
<span class="line"><span>Codex：生成了一个基本网页</span></span></code></pre></div><p><strong>第二轮（发现问题）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：页面太简单了，加一个项目展示区域</span></span>
<span class="line"><span>Codex：添加了项目展示区域</span></span></code></pre></div><p><strong>第三轮（继续优化）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：把主色调改成蓝色，字体换成更大的</span></span>
<span class="line"><span>Codex：修改了颜色和字体</span></span></code></pre></div><p><strong>第四轮（最终验收）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：很好，现在帮我把代码保存为 index.html</span></span>
<span class="line"><span>Codex：保存完成</span></span></code></pre></div><h3 id="关键技巧" tabindex="-1">关键技巧 <a class="header-anchor" href="#关键技巧" aria-label="Permalink to &quot;关键技巧&quot;">​</a></h3><ul><li><strong>不要怕说&quot;不对&quot;</strong>：如果结果不满意，直接告诉 Codex 哪里不对</li><li><strong>给具体反馈</strong>：不要说&quot;不好看&quot;，要说&quot;把标题字体加大&quot;、&quot;增加一些间距&quot;</li><li><strong>分步推进</strong>：大任务拆成小步骤，一步一步来</li></ul><hr><h2 id="四、实操-让-codex-根据你的描述创建一个网页" tabindex="-1">四、实操：让 Codex 根据你的描述创建一个网页 <a class="header-anchor" href="#四、实操-让-codex-根据你的描述创建一个网页" aria-label="Permalink to &quot;四、实操：让 Codex 根据你的描述创建一个网页&quot;">​</a></h2><h3 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to &quot;任务&quot;">​</a></h3><p>用 Codex 创建一个简单的个人简介网页。</p><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>打开 Codex，创建一个新的工作区（比如桌面上的&quot;我的网页&quot;文件夹）</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个个人简介网页，包含以下内容：</span></span>
<span class="line"><span>- 顶部：一张圆形头像占位符 + 姓名 + 一句话简介</span></span>
<span class="line"><span>- 中间：技能列表（用标签形式展示）</span></span>
<span class="line"><span>- 底部：联系方式（邮箱和社交媒体链接）</span></span>
<span class="line"><span>整体风格要简洁现代，使用蓝色作为主色调</span></span></code></pre></div></li><li>观察 Codex 生成的 HTML 代码</li><li>将代码保存为 <code>index.html</code>，在浏览器中打开查看效果</li><li>根据看到的实际效果，继续提出修改要求</li></ol><h3 id="可能的追问示例" tabindex="-1">可能的追问示例 <a class="header-anchor" href="#可能的追问示例" aria-label="Permalink to &quot;可能的追问示例&quot;">​</a></h3><ul><li>&quot;把头像从圆形改成圆角方形&quot;</li><li>&quot;在技能列表下面加一个项目展示区域&quot;</li><li>&quot;把配色方案改成深色模式&quot;</li></ul><hr><h2 id="五、本节实操任务清单" tabindex="-1">五、本节实操任务清单 <a class="header-anchor" href="#五、本节实操任务清单" aria-label="Permalink to &quot;五、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 尝试用&quot;差的指令&quot;让 Codex 做一件事，感受模糊指令的问题</li><li>[ ] 用&quot;好的指令&quot;重新描述同一个任务，对比结果差异</li><li>[ ] 完成上面的网页创建实操，至少进行 3 轮追问</li><li>[ ] 总结：你觉得写指令最难的部分是什么？</li></ul><hr><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>Vibe Coding</td><td>用自然语言描述目标，AI 来完成</td></tr><tr><td>好指令四要素</td><td>动作 + 对象 + 规则 + 期望结果</td></tr><tr><td>追问和修正</td><td>不追求一次完美，学会分步优化</td></tr><tr><td>指令模板</td><td>文件操作 / 内容生成 / 数据分析三类模板</td></tr></tbody></table><hr><h2 id="七、下一步" tabindex="-1">七、下一步 <a class="header-anchor" href="#七、下一步" aria-label="Permalink to &quot;七、下一步&quot;">​</a></h2><p><a href="./lesson-10.html">→ 第 10 课：联网与资料检索</a></p>`,61)])])}const g=t(n,[["render",i]]);export{c as __pageData,g as default};
